-- join_build_sql fill
create temp table "w" on commit drop as select rg."g", h.__hc, coalesce(h.__on, 0) as __on, coalesce(n.__rn, 0) as __rn from (select distinct "g" from pg_temp."trellis_join_rp_7") rg left join (select x.ctid as __hc, x."g", x.__n as __on from "trellis"."join_7_p" x) h on array[h."g"] = array[rg."g"] left join (select * from pg_temp."g" where not __meta) n on array[n."g"] = array[rg."g"]

-- join_build_sql write
with snap as materialized (select __snap, __seg from pg_temp."g" where __meta), up as ( update "trellis"."join_7_p" u set __n = r.__rn, __basis = snap.__snap, __stamp = snap.__seg from pg_temp."w" r, snap where u.ctid = r.__hc returning r.__hc ), ins as ( insert into "trellis"."join_7_p" ("g", __n, __basis, __stamp) select r."g", r.__rn, snap.__snap, snap.__seg from pg_temp."w" r, snap where not exists (select from up where up.__hc = r.__hc) order by r."g" ), d as (insert into pg_temp."d" ("g", __dn) select r."g", r.__rn - r.__on from pg_temp."w" r) select count(*) from pg_temp."w"

